package com.aistock.gateway.adminmarket;
import com.aistock.common.*;import com.aistock.common.marketreview.MarketReviewContract;import com.aistock.common.marketreview.MarketReviewContract.*;import com.aistock.gateway.*;import com.aistock.gateway.security.AdminReadAccess;import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.core.JsonParser;import jakarta.servlet.http.*;import java.io.IOException;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.util.MultiValueMap;import org.springframework.web.bind.annotation.*;
@RestController public class MarketReviewProxyController {
 private final MarketReviewPublicClient client;private final AdminReadAccess access;private final ObjectMapper mapper;private final Set<String> origins;
 public MarketReviewProxyController(MarketReviewPublicClient client,AdminReadAccess access,ObjectMapper mapper,@Value("${aistock.auth.allowed-origins:http://127.0.0.1:15173,http://localhost:15173}")String origins){this.client=client;this.access=access;this.mapper=mapper.copy().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS).enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION);this.origins=Set.copyOf(Arrays.stream(origins.split(",")).map(String::strip).toList());}
 @RequestMapping({"/api/v1/admin/market-data/{stock}/versions/{version}/reviews","/api/v1/admin/market-data/{stock}/versions/{version}/reviews/{operation}"})
 public ResponseEntity<byte[]> handle(@PathVariable String stock,@PathVariable String version,@PathVariable(required=false)String operation,@RequestParam MultiValueMap<String,String> query,HttpServletRequest r,HttpServletResponse response)throws IOException{
  response.setHeader("Cache-Control","no-store");boolean post="POST".equals(r.getMethod());if(!(post?MarketReviewContract.writePath(r.getRequestURI()):"GET".equals(r.getMethod())&&MarketReviewContract.readPath(r.getRequestURI())))throw new BusinessException("RESOURCE_NOT_FOUND","接口不存在",HttpStatus.NOT_FOUND);
  access.requireAdmin(r);if(!query.isEmpty())throw MarketReviewContract.invalid();byte[] body=null;Command command=null;
  if(post){if(!origins.contains(single(r,"Origin"))||!"1".equals(single(r,"X-Aistock-Admin-Action")))throw new BusinessException("TASK_ACTION_ORIGIN_DENIED","当前来源不允许提交操作",HttpStatus.FORBIDDEN);try{var type=MediaType.parseMediaType(single(r,"Content-Type"));if(!"application".equals(type.getType())||!"json".equals(type.getSubtype()))throw MarketReviewContract.invalid();}catch(RuntimeException e){throw MarketReviewContract.invalid();}if(r.getContentLengthLong()>4096)throw MarketReviewContract.invalid();body=r.getInputStream().readNBytes(4097);command=MarketReviewContract.parse(body);}else if(r.getInputStream().read()!=-1)throw MarketReviewContract.invalid();
  try{ResponseEntity<byte[]> reply;try{reply=post?client.post(r.getRequestURI().substring(8),body,ProxyHeaderPolicy.request(r)):client.get(r.getRequestURI().substring(8),ProxyHeaderPolicy.request(r));}catch(feign.FeignException e){reply=ResponseEntity.status(e.status()>0?e.status():503).body(e.content());}if(reply==null||reply.getBody()==null||reply.getBody().length>65536)throw unavailable();var n=mapper.reader().with(DeserializationFeature.FAIL_ON_TRAILING_TOKENS).readTree(reply.getBody());if(n==null||!n.isObject())throw unavailable();int status=reply.getStatusCode().value();String code=n.path("code").asText();if(status!=200||!"OK".equals(code))throw upstream(status,code);Object data;
   try{byte[] bytes=mapper.writeValueAsBytes(n.get("data"));if(post||operation!=null){var receipt=MarketReviewContract.decodeReceipt(bytes,stock,version);if(post&&(!receipt.operationId().equals(command.operationId())||!receipt.revision().equals(""+(MarketReviewContract.revision(command.expectedRevision())+1))||!receipt.reviewState().equals(command.reviewState())||!receipt.note().equals(command.note()))||operation!=null&&!operation.equals(receipt.operationId()))throw unavailable();data=receipt;}else data=MarketReviewContract.decodePage(bytes,stock,version);}catch(RuntimeException e){throw unavailable();}
   return ResponseEntity.ok().contentType(MediaType.APPLICATION_JSON).cacheControl(CacheControl.noStore()).body(mapper.writeValueAsBytes(ApiResponse.success(data,TraceIds.normalize(r.getHeader("X-Trace-Id")))));
  }catch(BusinessException e){throw e;}catch(IOException|RuntimeException e){throw unavailable();}
 }
 private String single(HttpServletRequest r,String name){var values=Collections.list(r.getHeaders(name));return values.size()==1?values.get(0):"";}
 private BusinessException upstream(int status,String code){if(status==400&&"REVIEW_REQUEST_INVALID".equals(code))return MarketReviewContract.invalid();if(status==401&&"AUTH_REQUIRED".equals(code))return new BusinessException(code,"请重新登录",HttpStatus.UNAUTHORIZED);if(status==403&&Set.of("ACCESS_DENIED","TASK_ACTION_ORIGIN_DENIED").contains(code))return new BusinessException(code,"当前账号或来源不允许审核",HttpStatus.FORBIDDEN);if(status==404&&Set.of("MARKET_ADMIN_RESOURCE_NOT_FOUND","REVIEW_OPERATION_NOT_FOUND").contains(code))return new BusinessException(code,"目前未查到对应记录，请保留原操作编号核对",HttpStatus.NOT_FOUND);if(status==409&&Set.of("REVIEW_OPERATION_CONFLICT","REVIEW_REVISION_CONFLICT").contains(code))return new BusinessException(code,"记录或操作编号已变化，请核对后重新加载",HttpStatus.CONFLICT);if(status==503&&"USER_SERVICE_UNAVAILABLE".equals(code))return new BusinessException(code,"账号服务暂不可用",HttpStatus.SERVICE_UNAVAILABLE);return unavailable();}
 private BusinessException unavailable(){return new BusinessException("MARKET_ADMIN_UNAVAILABLE","审核结果暂无法确认，请查询原操作编号",HttpStatus.SERVICE_UNAVAILABLE);}
}
